  CPen p(PS_SOLID,width,c); CPen* op=dc->SelectObject(&p);
  HBRUSH nb=(HBRUSH)GetStockObject(NULL_BRUSH); HBRUSH ob=(HBRUSH)dc->SelectObject(nb);
  dc->RoundRect(r,CPoint(rad,rad)); dc->SelectObject(op); dc->SelectObject(ob);
